from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


_CENT = Decimal("0.01")
_ZERO = Decimal(0)
_HUNDRED = Decimal(100)


def _decimal(value: Any) -> Decimal:
    """Apply legacy NVL(value, 0) numeric coercion without float artifacts."""
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _precision_for(values: list[Decimal], line_count: int) -> int:
    """Choose sufficient precision for exact intermediate arithmetic."""
    width = 0
    for value in values:
        digits = len(value.as_tuple().digits)
        magnitude = value.adjusted() + 3 if value else 1
        width += max(1, digits, magnitude)
    return max(50, width + len(str(max(1, line_count))) + 20)


def recompute(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list]:
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    numeric_values = [
        _decimal(order.get("DISC_PCT")),
        _decimal(order.get("TOT_AMT")),
    ]
    for line in lines:
        if line.get("DEL_FLG") != "Y":
            numeric_values.append(_decimal(line.get("QTY")))
            numeric_values.append(_decimal(line.get("UNIT_PRC")))

    audits: list[tuple[str, Any]] = []

    with localcontext() as context:
        context.prec = _precision_for(numeric_values, len(lines))

        total = _ZERO

        for source_line, returned_line in zip(lines, new_lines):
            if source_line.get("DEL_FLG") == "Y":
                continue

            quantity = _decimal(source_line.get("QTY"))
            unit_price = _decimal(source_line.get("UNIT_PRC"))
            extended = (quantity * unit_price).quantize(
                _CENT, rounding=ROUND_HALF_UP
            )

            returned_line["EXT_AMT"] = float(extended)
            total += extended

        discount_percent = _decimal(order.get("DISC_PCT"))
        discounted = (
            total * (_HUNDRED - discount_percent) / _HUNDRED
        ).quantize(_CENT, rounding=ROUND_HALF_UP)

        incoming_total = _decimal(order.get("TOT_AMT"))
        new_order["TOT_AMT"] = float(discounted)

        if incoming_total != discounted:
            audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
